db = {"u7": {"plan": "free"}}
cache = {}

def read_user(uid):
    if uid not in cache:
        cache[uid] = dict(db[uid])
    return cache[uid]

def upgrade_write_around(uid):
    db[uid]["plan"] = "pro"          # updates the store, leaves the cache alone

def upgrade_write_through(uid):
    db[uid]["plan"] = "pro"
    cache.pop(uid, None)             # same operation also invalidates

