TTL = 10
db = {"stock:widget": 50}
cache = {}
now = 0
stale_reads = 0
reads = 0

def read_stock():
    global reads, stale_reads
    reads += 1
    e = cache.get("stock:widget")
    if e is None or now - e[1] >= TTL:
        cache["stock:widget"] = (db["stock:widget"], now)
        return db["stock:widget"]
    if e[0] != db["stock:widget"]:
        stale_reads += 1
    return e[0]

# 40 ticks of steady traffic; a sale lands at t=3, a restock at t=12
for t in range(40):
    now = t
    if t == 3:
        db["stock:widget"] = 49
    if t == 12:
        db["stock:widget"] = 80
    read_stock()

print("total reads:                                    ", reads)
print("reads served a value the db no longer held:     ", stale_reads)

