class Query:
    def __init__(self, term):
        self.term = term
    def __hash__(self):
        return hash(self.term)
    def __eq__(self, other):
        return isinstance(other, Query) and self.term == other.term

cache = {}
q = Query("shoes")
cache[q] = "results for shoes"

q.term = "hats"      # a caller mutates the object after it became a key

print("lookup Query('shoes'):", cache.get(Query("shoes"), "<miss - entry orphaned>"))
print("lookup Query('hats'): ", cache.get(Query("hats"), "<miss>"), "<- serves the SHOES results")
print("entries stored in cache:", len(cache))

db = {"stock": (40, 7)}   # (value, version)
cache = {}

def read_through():
    return db["stock"]            # snapshot: (value, version it came from)

def cas_store(value, version_seen):
    if db["stock"][1] == version_seen:
        cache["stock"] = (value, version_seen)
        return "stored"
    return "refused: db has moved to v" + str(db["stock"][1])

value, seen = read_through()      # reader snapshots stock=40 at v7, starts recomputing
db["stock"] = (35, 8)             # a sale lands mid-recompute: stock 35, v8

print("reader tries to store its snapshot:", cas_store(value, seen))
value, seen = read_through()      # next reader snapshots the current state
print("fresh snapshot stores:             ", cas_store(value, seen))
print("cache now holds:                   ", cache["stock"])

