attempts = {"n": 0}
memo = {}

def fetch_config(key):
    attempts["n"] += 1
    if attempts["n"] == 1:
        raise ConnectionError("config service blip")
    return {"theme": "dark"}

def get_config(key):
    if key not in memo:
        try:
            memo[key] = fetch_config(key)
        except ConnectionError as e:
            memo[key] = e            # the failure itself gets memoized
    return memo[key]

