primary = {"display_name": "Ana"}
replica = {"display_name": "Ana"}
LAG = 3
pending = []
now = 0

def write(name):
    primary["display_name"] = name
    pending.append((now + LAG, name))        # replication applies it LAG ticks later

def tick():
    global now
    now += 1
    for apply_at, value in list(pending):
        if apply_at <= now:
            replica["display_name"] = value
            pending.remove((apply_at, value))

def page():
    return replica["display_name"]           # the profile page reads the replica

write("Ana M.")                              # the user saves at t=0
print("t=0 primary:", primary["display_name"], "| profile page shows:", page())
tick(); print("t=1 profile page shows:", page())
tick(); print("t=2 profile page shows:", page())
tick(); print("t=3 profile page shows:", page(), "<- her own edit, finally visible to her")

