rows = [("a", 30), ("a", 10), ("b", 45), ("c", 25)]   # source: transaction rows
stored = {"a": 40, "b": 40, "c": 25}                  # derived totals; b has drifted

def recompute(rows):
    totals = {}
    for acct, amt in rows:
        totals[acct] = totals.get(acct, 0) + amt
    return totals

truth = recompute(rows)
for acct in sorted(truth):
    mark = "" if stored[acct] == truth[acct] else "   <- DRIFT"
    print(f"{acct}: stored={stored[acct]}  recomputed={truth[acct]}{mark}")

stored.update(truth)                                   # the repair: rebuild from source
print("after rebuild, stored == recomputed:", stored == recompute(rows))

